}

.mention-author {
  font-size: 13px;
  font-weight: 600;
}

.gender-chip {
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--green);
  background: var(--green-soft);
  border: 1px solid rgba(41, 114, 169, 0.14);
  padding: 3px 8px;
  border-radius: 999px;
}

.mention-date {
  font-size: 10px;
  color: var(--muted);
  margin-left: auto;
}

.mention-text {
  font-size: 13px;
  line-height: 1.6;
  color: var(--text);
  white-space: pre-wrap;
}

.mention-post {
  font-size: 10px;
  color: var(--gold-bright);
}

