appsmith.onReady(function () {
  var navMenu = document.getElementById('navMenu');

  function decodeB64(s) {
    if (!s) { return null; }
    try { return JSON.parse(decodeURIComponent(escape(atob(s)))); } catch (e) { return null; }
  }

  function esc(s) {
    var d = document.createElement('div');
    d.textContent = s == null ? '' : String(s);
    return d.innerHTML;
  }

  var PLAT_NAMES = {
    instagram: 'Instagram', tiktok: 'TikTok', facebook: 'Facebook', x: 'X (Twitter)',
    reddit: 'Reddit', threads: 'Threads', bluesky: 'Bluesky', snapchat: 'Snapchat',
    truth_social: 'Truth Social', youtube: 'YouTube', rumble: 'Rumble', twitch: 'Twitch',
    kwai: 'Kwai', kick: 'Kick', linkedin: 'LinkedIn', github: 'GitHub', telegram: 'Telegram',
    tiktok_shop: 'TikTok Shop', facebook_marketplace: 'FB Marketplace', facebook_events: 'FB Events',
    facebook_ad_library: 'FB Ad Library', tiktok_ad_library: 'TikTok Ad Library',
    google_ad_library: 'Google Ad Library', linkedin_ad_library: 'LinkedIn Ad Library',
    spotify: 'Spotify', apple_music: 'Apple Music', soundcloud: 'SoundCloud',
    google: 'Google', pinterest: 'Pinterest'
  };

  var PLAT_COLORS = {
    instagram: '#2E9BCB',
    tiktok: '#2F323B',
    facebook: '#2972A9',
    x: '#2F323B',
    reddit: '#585A61',
    threads: '#585A61',
    bluesky: '#2E9BCB',
    snapchat: '#2972A9',
    truth_social: '#585A61',
    youtube: '#2972A9',
    rumble: '#585A61',
    twitch: '#2E9BCB',
    kwai: '#2972A9',
    kick: '#585A61',
    linkedin: '#2972A9',
    github: '#2F323B',
    telegram: '#2E9BCB',
    tiktok_shop: '#585A61',
    facebook_marketplace: '#2972A9',
    facebook_events: '#2E9BCB',
    facebook_ad_library: '#2972A9',
    tiktok_ad_library: '#2E9BCB',
    google_ad_library: '#2972A9',
    linkedin_ad_library: '#2F323B',
    spotify: '#585A61',
    apple_music: '#2E9BCB',
    soundcloud: '#2972A9',
    google: '#585A61',
    pinterest: '#2F323B'
  };

  var GENDER_LABEL = {
    FEMALE: 'Femenino',
    MALE: 'Masculino',
    NEUTER: 'Organización',
    UNKNOWN: 'Sin dato'
  };

  function platName(code) {
    return PLAT_NAMES[code] || code;
  }

  function platColor(code) {
    return PLAT_COLORS[code] || '#2972A9';
  }

  var role = 'viewer';

  try {
    var model = appsmith.model || {};
    role = model.userRole || 'viewer';
    var email = model.userEmail || '';
    var active = model.active || 'dashboard';

    document.getElementById('userEmail').textContent = email;
    document.getElementById('userRole').textContent = role.toUpperCase();
    document.getElementById('userAvatar').textContent = email.charAt(0).toUpperCase() || 'A';

    var MENU = [
      {
        section: 'Análisis',
        items: [
          { id: 'dashboard', label: 'Dashboard', roles: ['admin', 'analyst', 'viewer'] },
          { id: 'mentions', label: 'Menciones', roles: ['admin', 'analyst', 'viewer'] },
          { id: 'analytics', label: 'Analítica', roles: ['admin', 'analyst'] },
          { id: 'competitors', label: 'Competencia', roles: ['admin', 'analyst'] }
        ]
      },
      {
        section: 'Gestión',
        items: [
          { id: 'targets', label: 'Objetivos', roles: ['admin', 'analyst'] },
          { id: 'alerts', label: 'Alertas', roles: ['admin', 'analyst', 'viewer'] },
          { id: 'reports', label: 'Reportes', roles: ['admin', 'analyst', 'viewer'] }
        ]
      },
      {
        section: 'Administración',
        items: [
          { id: 'tasks', label: 'Tareas de Scrapeo', roles: ['admin'] },
          { id: 'integrations', label: 'Integraciones', roles: ['admin'] },
          { id: 'users', label: 'Usuarios', roles: ['admin'] },
          { id: 'roles', label: 'Roles y Permisos', roles: ['admin'] },
          { id: 'audit', label: 'Auditoría', roles: ['admin'] },
          { id: 'settings', label: 'Configuración', roles: ['admin'] },
          { id: 'billing', label: 'Plan y Suscripción', roles: ['admin'] }
        ]
      }
    ];

    var TITLES = {
      dashboard: 'Dashboard Ejecutivo',
      mentions: 'Menciones',
      analytics: 'Analítica',
      competitors: 'Competencia',
      targets: 'Objetivos Monitoreados',
      alerts: 'Alertas',
      reports: 'Reportes',
      tasks: 'Tareas de Scrapeo',
      integrations: 'Integraciones',
      users: 'Usuarios',
      roles: 'Roles y Permisos',
      audit: 'Auditoría',
      settings: 'Configuración',
      billing: 'Plan y Suscripción'
    };

    navMenu.innerHTML = '';

    MENU.forEach(function (section) {
      var visible = [];

      for (var i = 0; i < section.items.length; i++) {
        if (section.items[i].roles.indexOf(role) !== -1) {
          visible.push(section.items[i]);
        }
      }

      if (visible.length === 0) {
        return;
      }

      var containsActive = false;

      for (var j = 0; j < visible.length; j++) {
        if (visible[j].id === active) {
          containsActive = true;
        }
      }

      var group = document.createElement('li');
      group.className = 'nav-group' + (containsActive ? '' : ' collapsed');

      var head = document.createElement('div');
      head.className = 'nav-section-head';

      var headLabel = document.createElement('span');
      headLabel.textContent = section.section;
      head.appendChild(headLabel);

      head.addEventListener('click', function () {
        if (group.classList.contains('collapsed')) {
          group.classList.remove('collapsed');
        } else {
          group.classList.add('collapsed');
        }
      });

      group.appendChild(head);

      var list = document.createElement('ul');
      list.className = 'nav-group-items';

      visible.forEach(function (item) {
        var li = document.createElement('li');
        li.className = 'nav-item' + (item.id === active ? ' active' : '');
        li.textContent = item.label;

        li.addEventListener('click', function () {
          appsmith.triggerEvent('go_' + item.id);
        });

        list.appendChild(li);
      });

      group.appendChild(list);
      navMenu.appendChild(group);
    });

    document.getElementById('viewTitle').textContent =
      TITLES[active] || 'Dashboard Ejecutivo';

    document.getElementById('logoutBtn').addEventListener('click', function () {
      appsmith.triggerEvent('onLogout');
    });
  } catch (errShell) {
    navMenu.innerHTML =
      '<li style="color:#A7CDDE;padding:12px;font-size:11px;">ERROR SHELL: ' +
      errShell.message +
      '</li>';

    return;
  }

  if ((appsmith.model || {}).active === 'mentions') {
    try {
      initMentionsModule();
    } catch (errMod) {
      var area = document.getElementById('contentArea');

      if (area) {
        area.innerHTML =
          '<div style="color:#2F323B;background:rgba(167,205,222,0.18);border:1px solid rgba(167,205,222,0.65);border-radius:10px;padding:14px;font-size:12px;">ERROR MODULO: ' +
          errMod.message +
          '</div>';
      }
    }
  }

  function renderMentions(data) {
    var area = document.getElementById('contentArea');

    if (!area) {
      return;
    }

    if (!data) {
      area.innerHTML =
        '<div class="empty-state">' +
          '<h4>Cargando menciones…</h4>' +
          '<p>El feed se poblará al recibir comentarios del pipeline.</p>' +
        '</div>';

      return;
    }

    var list = data.list || [];
    var top = data.top || [];

    var autores = {};

    list.forEach(function (m) {
      autores[m.author_name] = true;
    });

    var totalAutores = Object.keys(autores).length;

    var topRows = '';

    top.forEach(function (t) {
      topRows +=
        '<tr>' +
          '<td class="cell-strong">' +
            esc(t.author_name) +
          '</td>' +
          '<td>' +
            esc(t.menciones) +
          '</td>' +
        '</tr>';
    });

    var cards = '';

    list.forEach(function (m) {
      var postEx = (m.post_texto || '')
        .replace(/\s+/g, ' ')
        .slice(0, 80);

      cards +=
        '<div class="mention-card">' +
          '<div class="mention-head">' +
            '<span class="plat-badge" style="background:' +
              platColor(m.platform) +
            '">' +
              esc(platName(m.platform)) +
            '</span>' +

            '<span class="mention-author">' +
              esc(m.author_name) +
            '</span>' +

            '<span class="gender-chip">' +
              esc(GENDER_LABEL[m.author_gender] || 'Sin dato') +
            '</span>' +

            '<span class="mention-date">' +
              esc(
                m.published_at
                  ? String(m.published_at).slice(0, 16).replace('T', ' ')
                  : ''
              ) +
            '</span>' +
          '</div>' +

          '<p class="mention-text">' +
            esc(m.content_text) +
          '</p>' +

          '<span class="mention-post">En: ' +
            esc(postEx) +
          '…</span>' +
        '</div>';
    });

    area.innerHTML =
      '<div class="kpi-grid">' +

        '<div class="kpi-card">' +
          '<span class="kpi-label">Menciones recientes</span>' +
          '<span class="kpi-value">' +
            list.length +
          '</span>' +
          '<span class="kpi-sub">últimas 50 registradas</span>' +
        '</div>' +

        '<div class="kpi-card">' +
          '<span class="kpi-label">Autores únicos</span>' +
          '<span class="kpi-value">' +
            totalAutores +
          '</span>' +
          '<span class="kpi-sub">en el feed reciente</span>' +
        '</div>' +

      '</div>' +

      '<section class="table-panel">' +
        '<div class="panel-head">' +
          '<h3>Top autores por menciones</h3>' +
        '</div>' +

        '<table class="sl-table">' +
          '<thead>' +
            '<tr>' +
              '<th>Autor</th>' +
              '<th>Menciones</th>' +
            '</tr>' +
          '</thead>' +

          '<tbody>' +
            (
              topRows ||
              '<tr>' +
                '<td colspan="2" class="cell-muted">Sin datos aún.</td>' +
              '</tr>'
            ) +
          '</tbody>' +
        '</table>' +
      '</section>' +

      '<section class="table-panel">' +
        '<div class="panel-head">' +
          '<h3>Feed de menciones</h3>' +
        '</div>' +

        (
          cards ||
          '<div class="empty-state">' +
            '<h4>Sin menciones aún</h4>' +
            '<p>Ejecuta el pipeline en n8n para ingerir comentarios.</p>' +
          '</div>'
        ) +
      '</section>';
  }

  function initMentionsModule() {
    renderMentions(
      decodeB64(appsmith.model.mentionsJson)
    );

    var last = appsmith.model.mentionsJson || '';

    function refresh() {
      var now = appsmith.model.mentionsJson || '';

      if (now !== last) {
        last = now;

        renderMentions(
          decodeB64(now)
        );
      }
    }

    if (typeof appsmith.onModelChange === 'function') {
      appsmith.onModelChange(refresh);
    } else {
      setInterval(refresh, 1500);
    }

    setTimeout(function () {
      appsmith.triggerEvent('onLoadData');
    }, 300);
  }
});
